from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()  # Set of all book IDs in the library
        # Dictionary mapping user -> list of (book_id, borrow_date, return_date, fine)
        # return_date is None if not returned yet
        self.user_books = {}
        # Dictionary mapping user -> list of unpaid fines (float values)
        self.user_fines = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} not in library")

        # Check if user already has an unpaid book
        if user in self.user_books:
            # Find if user has any book that hasn't been returned yet
            has_unreturned = False
            for book_info in self.user_books[user]:
                if book_info[2] is None:  # return_date is None means not returned
                    has_unreturned = True
                    break
            if has_unreturned:
                # User already has an unreturned book
                # Check if they have unpaid fines - if so, they can only hold one book
                # But the requirement says "may hold at most one book at a time", 
                # so we need to ensure they don't have more than one unreturned book
                unreturned_count = sum(1 for book_info in self.user_books[user] if book_info[2] is None)
                if unreturned_count >= 1:
                    raise ValueError(f"User {user} already has a borrowed book")

        # Initialize user's book list if not exists
        if user not in self.user_books:
            self.user_books[user] = []

        # Record the borrow
        self.user_books[user].append((book_id, day, None, 0.0))

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if user not in self.user_books:
            raise ValueError(f"User {user} has not borrowed any books")

        # Find the book in user's borrowed books that hasn't been returned yet
        book_found = False
        fine = 0.0

        for i, (b_id, borrow_date, return_date, existing_fine) in enumerate(self.user_books[user]):
            if b_id == book_id and return_date is None:
                book_found = True
                # Calculate fine
                due_date = borrow_date + timedelta(days=self.loan_days)

                # Count business days (Mon-Fri) between due_date and day (inclusive of day after due_date)
                if day > due_date:
                    delay_days = 0
                    current = due_date + timedelta(days=1)
                    while current <= day:
                        # Only count Monday-Friday (weekday() returns 0-6, where 0=Monday, 6=Sunday)
                        if current.weekday() < 5:  # Monday=0, Friday=4
                            delay_days += 1
                        current += timedelta(days=1)

                    fine = delay_days * self.daily_fine

                # Update the record with return date and fine
                self.user_books[user][i] = (book_id, borrow_date, day, fine)

                # Add to user's unpaid fines
                if user not in self.user_fines:
                    self.user_fines[user] = []
                self.user_fines[user].append(fine)

                break

        if not book_found:
            raise ValueError(f"User {user} has not borrowed book {book_id}")

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.user_fines:
            return 0.0
        return sum(self.user_fines[user])

    def pay(self, user: str) -> None:
        if user in self.user_fines:
            self.user_fines[user] = []
